package com.minenorth_eurobank.braquage.item;
import com.minenorth_eurobank.EuroBank; import com.minenorth_eurobank.braquage.block.ModBlocks; import net.minecraft.world.item.BlockItem; import net.minecraft.world.item.Item; import net.minecraftforge.registries.DeferredRegister; import net.minecraftforge.registries.ForgeRegistries; import net.minecraftforge.registries.RegistryObject;
public class ModItems{public static final DeferredRegister<Item> ITEMS=DeferredRegister.create(ForgeRegistries.ITEMS,EuroBank.MODID); public static final RegistryObject<Item> BANK_VAULT=ITEMS.register("bank_vault",()->new BlockItem(ModBlocks.BANK_VAULT.get(),new Item.Properties())); public static final RegistryObject<Item> HACKER=ITEMS.register("hacker",()->new HackerItem(new Item.Properties())); public static final RegistryObject<Item> DRILL=ITEMS.register("drill",()->new DrillItem(DrillItem.DrillLevel.I,new Item.Properties())); public static final RegistryObject<Item> DRILL_MK2=ITEMS.register("drill_mk2",()->new DrillItem(DrillItem.DrillLevel.II,new Item.Properties())); public static final RegistryObject<Item> DRILL_MK3=ITEMS.register("drill_mk3",()->new DrillItem(DrillItem.DrillLevel.III,new Item.Properties()));}
